// AccessToken Access token.
type AccessToken struct {
	// AccessToken Access token acts as a session ID that the application uses for making
	// requests. This token should be protected as if it were user
	// credentials.
	//
	//
	// Example: 7133au-cba5a72-842029c
	AccessToken string `json:"access_token"`

	// Expiration The time when the token is expired is represented as the number of
	// seconds since the Unix epoch (00:00:00 UTC on 1 January 1970).
	//
	//
	// Example: 1548661401
	Expiration float64 `json:"expiration"`
}

// Account defines model for Account.
type Account struct {
	Config AccountFlags `json:"config"`

	// ConnectWarningConfig A message that is displayed to users right after the authentication process is finished.
	// One of the use cases is displaying regulatory required message.
	ConnectWarningConfig *ConnectWarningConfig `json:"connectWarningConfig,omitempty"`

	// Currency Abbreviation of account currency.
	//
	// Example: JPY
	Currency *string `json:"currency,omitempty"`

	// CurrencySign Account currency symbol.
	//
	// Example: ¥
	CurrencySign *string `json:"currencySign,omitempty"`

	// Durations Localized array of durations displayed in the Order Ticket.
	// It will override values, specified in the [/config](#operation/getConfiguration) endpoint.
	Durations *AccountDurations `json:"durations,omitempty"`

	// Id Unique account identifier. The uniqueness of the account ID ensures the correct operation of the broker review functionality.
	//
	// Example: ACC-001
	Id string `json:"id"`

	// IsVerified Used to confirm that the account has been verified (for example, KYC is passed). Only verified account users can leave reviews in the broker profile.
	//
	// Example: true
	IsVerified *bool `json:"isVerified,omitempty"`

	// Name Account title that is displayed to a user.
	//
	// Example: Demo trading account
	Name string `json:"name"`

	// Prefix Limits the Symbol Search to show only tradeable symbols with this prefix for current sub-account.
	//
	// Example: NASDAQ
	Prefix *string `json:"prefix,omitempty"`

	// TradingOptionsSets Key-value set of custom GUI options specific for a set of instruments.
	// The key is the name ot the set of options. The instruments that use an option set should be configured in [/instruments](#operation/getInstruments) with the same value in the `tradingOptionsSet` field.
	// These values will override the configuration specified in the [/account](#operation/getAccounts) endpoint.
	// If `supportStopLoss`, `supportTrailingStop` and `supportGuaranteedStop` are set to `false`, `supportStopLoss` will be enabled.
	TradingOptionsSets *TradingOptionsSets `json:"tradingOptionsSets,omitempty"`

	// Type Account type
	//
	// Example: demo
	Type AccountType `json:"type"`

	// Ui Account manager and Order dialog configuration for the account.
	// The Account manager configuration will override configuration, specified in the [/config](#operation/getConfiguration) endpoint.
	Ui *struct {
		// AccountManager Localized Account manager's tables configuration. Account manager is a
		// page in the bottom widget. This page can have multiple tables. Data of
		// the tables is filled using the [/state](/rest-api-spec/#operation/getState) endpoint.
		//
		//
		// Example: [{"columns":[{"id":"todayPL","title":"Today's P\u0026L"},{"id":"accountValue","title":"Account Value"},{"id":"balance","title":"Balance"},{"id":"totalMargin","title":"Margin"},{"id":"held","title":"Held"},{"id":"buyingPower","title":"Buying Power"}],"id":"accountSummary","title":""}]
		AccountManager *AccountManager `json:"accountManager,omitempty"`

		// AccountSummaryRow Localized Account Summary Row configuration.
		// Account Summary Row is a panel at the top of the bottom widget with the key account indicators. The `supportCustomAccountSummaryRow` flag should be enabled in the account config, see the [/accounts](#operation/getAccounts) endpoint. Data of the Account Summary Row is filled using the [/state](/rest-api-spec/#operation/getState) endpoint.
		//
		// Example: [{"id":"accountBalance","title":"Account Balance"},{"id":"Equity","title":"Realized P/L"},{"id":"Open Profit","title":"Unrealized P/L"}]
		AccountSummaryRow *AccountSummaryRow `json:"accountSummaryRow,omitempty"`

		// ExitLevelsConfig Exit levels configuration.
		ExitLevelsConfig *ExitLevelsConfig `json:"exitLevelsConfig,omitempty"`

		// IndividualPositionCustomFields Additional position columns to be displayed in the positions table of the Account manager.
		// The positions table has a default set of columns that can be extended using this configuration.
		// The `supportPositionCustomFields` flag should be enabled in the [account configuration](https://www.tradingview.com/rest-api-spec/#operation/getAccounts).
		// Data of the additional fields is filled from the
		// [/positions](https://www.tradingview.com/rest-api-spec/#operation/getPositions) `customFields` value.
		//
		//
		// Example: [{"alignment":"right","id":"exchangeFee","title":"Exchange fee","tooltip":"Exchange fee for the position"},{"alignment":"right","id":"routeFee","title":"Route fee","tooltip":"Route fee for the position"}]
		IndividualPositionCustomFields *PositionCustomFields `json:"individualPositionCustomFields,omitempty"`

		// NetPositionCustomFields Additional position columns to be displayed in the positions table of the Account manager.
		// The positions table has a default set of columns that can be extended using this configuration.
		// The `supportPositionCustomFields` flag should be enabled in the [account configuration](https://www.tradingview.com/rest-api-spec/#operation/getAccounts).
		// Data of the additional fields is filled from the
		// [/positions](https://www.tradingview.com/rest-api-spec/#operation/getPositions) `customFields` value.
		//
		//
		// Example: [{"alignment":"right","id":"exchangeFee","title":"Exchange fee","tooltip":"Exchange fee for the position"},{"alignment":"right","id":"routeFee","title":"Route fee","tooltip":"Route fee for the position"}]
		NetPositionCustomFields *PositionCustomFields `json:"netPositionCustomFields,omitempty"`

		// OrderCustomFields Additional order columns to be displayed in the orders table of the Account manager.
		// The orders table has a default set of columns that can be extended using this configuration.
		// The `supportOrderCustomFields` flag should be enabled in the [account configuration](https://www.tradingview.com/rest-api-spec/#operation/getAccounts).
		// Data of the additional fields is filled from the
		// [/orders](https://www.tradingview.com/rest-api-spec/#operation/getOrders) `customFields` value.
		//
		//
		// Example: [{"alignment":"right","id":"commission","title":"Commission","tooltip":"Commission Fees"}]
		OrderCustomFields *OrderCustomFields `json:"orderCustomFields,omitempty"`

		// OrderDialogCustomFields Additional custom controls to be displayed in the Order dialog. At the moment, the possible control types are `comboBox`, `checkBox` and `textField`. Data of the additional fields is filled from the [/orders](#operation/getOrders) endpoint.
		OrderDialogCustomFields *OrderDialogCustomFields `json:"orderDialogCustomFields,omitempty"`

		// OrderDialogLinks Optional array of hyperlinks displayed to the user in the Order Ticket. Needs to be coordinated with TradingView team before enabling.
		OrderDialogLinks *[]Hyperlink `json:"orderDialogLinks,omitempty"`

		// OrderHistoryCustomFields Additional history columns to be displayed in the history table of the Account manager.
		// The history table has a default set of columns that can be extended using this configuration.
		// The `supportOrderHistoryCustomFields` and `supportOrdersHistory` flags should be enabled in the [account configuration](https://www.tradingview.com/rest-api-spec/#operation/getAccounts).
		// Data of the additional fields is filled from the
		// [/ordersHistory](/rest-api-spec/#operation/getOrdersHistory) `customFields` value.
		//
		//
		// Example: [{"alignment":"right","id":"commission","title":"Commission","tooltip":"Commission Fees"}]
		OrderHistoryCustomFields *OrderHistoryCustomFields `json:"orderHistoryCustomFields,omitempty"`

		// PositionCustomFields Additional position columns to be displayed in the positions table of the Account manager.
		// The positions table has a default set of columns that can be extended using this configuration.
		// The `supportPositionCustomFields` flag should be enabled in the [account configuration](https://www.tradingview.com/rest-api-spec/#operation/getAccounts).
		// Data of the additional fields is filled from the
		// [/positions](https://www.tradingview.com/rest-api-spec/#operation/getPositions) `customFields` value.
		//
		//
		// Example: [{"alignment":"right","id":"exchangeFee","title":"Exchange fee","tooltip":"Exchange fee for the position"},{"alignment":"right","id":"routeFee","title":"Route fee","tooltip":"Route fee for the position"}]
		PositionCustomFields *PositionCustomFields `json:"positionCustomFields,omitempty"`
	} `json:"ui,omitempty"`
}

// AccountType Account type
//
// Example: demo
type AccountType string

// AccountDurations Localized array of durations displayed in the Order Ticket.
